class Category(URLWrapper):
    @property
    def slug(self):
        if self._slug is None:
            if 'CATEGORY_REGEX_SUBSTITUTIONS' in self.settings:
                subs = self.settings['CATEGORY_REGEX_SUBSTITUTIONS']
